package com.rikkeibank.account.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="account_operations",uniqueConstraints=@UniqueConstraint(columnNames={"operation_id","operation_type"})) public class AccountOperation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="operation_id",nullable=false) private String operationId;@Column(name="operation_type",nullable=false) private String operationType;@Column(nullable=false) private Long accountId;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public String getOperationId(){return operationId;}public void setOperationId(String v){operationId=v;}public String getOperationType(){return operationType;}public void setOperationType(String v){operationType=v;}public Long getAccountId(){return accountId;}public void setAccountId(Long v){accountId=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
